forall X -> X null() asm "PUSHNULL";
slice parse(cell c) asm "CTOS";
int bits(slice s) asm "SBITS";
forall X -> (X, X) duplicate(X x) impure { return (x, x); }
forall X -> (X, X) forward(X x) impure { return duplicate(x); }
forall X -> X choose(X a, X b, int flag) impure {
  if (flag) { return a; }
  return b;
}
forall X -> (X, X) repeated(X x, int n) impure {
  var y = x;
  repeat(n) { (x, y) = forward(x); }
  return (x, y);
}
forall X -> X optional(X x, int flag) impure {
  if (flag) { return x; }
  return null();
}
() recv_internal() { }
(cell, cell) cells(cell c) method_id(100001) { return forward(c); }
(slice, slice) slices(slice s) method_id(100002) { return forward(s); }
(int, int) integers(int x) method_id(100003) { return forward(x); }
cell select_cell(cell a, cell b, int f) method_id(100004) { return choose(a,b,f); }
slice select_slice(slice a, slice b, int f) method_id(100005) { return choose(a,b,f); }
(cell, cell) loop_cell(cell c, int n) method_id(100006) { return repeated(c,n); }
(slice, slice) loop_slice(slice s, int n) method_id(100007) { return repeated(s,n); }
int use_result(cell c) method_id(100008) {
  var (a,b) = forward(c);
  return bits(parse(a)) + bits(parse(b));
}
slice select_nullable(slice s, int f) method_id(100009) { return choose(s,null(),f); }
slice optional_slice(slice s, int f) method_id(100010) { return optional(s,f); }
cell optional_cell(cell c, int f) method_id(100011) { return optional(c,f); }
forall X -> X while_value(X x, int n) impure method_id(100012) {
  while (n > 0) {
    var (a,b) = forward(x);
    x = a;
    n -= 1;
  }
  return x;
}
forall X -> (X, int) until_value(X x, int n) impure method_id(100013) {
  do {
    var (a,b) = forward(x);
    x = b;
    n -= 1;
  } until (n <= 0);
  return (x,n);
}
